(function () {
  var algo = new Object;
  algo.apiVersion = 3;
  algo.name = "Degradê rolando";
  algo.author = "R Light Control";
  algo.acceptColors = 2;
  algo.properties = [];
  var colors = [0xFF0000, 0x0000FF];

  algo.rgbMapSetColors = function (list) {
    colors = list;
  };

  // Mistura as duas cores: t = 0 é a primeira e t = 1, a segunda
  function mix(t) {
    var out = 0;
    for (var shift = 16; shift >= 0; shift -= 8) {
      var a = (colors[0] >> shift) & 255;
      var b = (colors[1] >> shift) & 255;
      out |= Math.round(a + (b - a) * t) << shift;
    }
    return out;
  }

  // O degradê vai da primeira cor à segunda e volta, e anda uma coluna por passo
  algo.rgbMap = function (width, height, rgb, step) {
    var map = new Array(height);
    for (var y = 0; y < height; y++) {
      map[y] = new Array(width);
      for (var x = 0; x < width; x++) {
        var p = ((x + step) % width) / width;
        map[y][x] = mix(p < 0.5 ? p * 2 : (1 - p) * 2);
      }
    }
    return map;
  };

  algo.rgbMapStepCount = function (width, height) {
    return width;
  };

  return algo;
})()

(function () {
  var algo = new Object;
  algo.apiVersion = 2;
  algo.name = "Onda";
  algo.author = "R Light Control";
  algo.acceptColors = 1;

  // Quantas colunas tem uma onda
  var length = 4;
  algo.properties = ["name:length|type:range|display:Comprimento|values:2,16|write:setLength|read:getLength"];
  algo.setLength = function (value) {
    length = parseInt(value, 10);
  };
  algo.getLength = function () {
    return length;
  };

  // Uma onda de brilho na cor do passo, que anda uma onda inteira a cada 16 passos
  algo.rgbMap = function (width, height, rgb, step) {
    var map = new Array(height);
    for (var y = 0; y < height; y++) {
      map[y] = new Array(width);
      for (var x = 0; x < width; x++) {
        var level = (Math.sin(2 * Math.PI * (x / length - step / 16)) + 1) / 2;
        var out = 0;
        for (var shift = 16; shift >= 0; shift -= 8) {
          out |= Math.round(((rgb >> shift) & 255) * level) << shift;
        }
        map[y][x] = out;
      }
    }
    return map;
  };

  algo.rgbMapStepCount = function (width, height) {
    return 16;
  };

  return algo;
})()

(function () {
  var algo = new Object;
  algo.apiVersion = 2;
  algo.name = "Faíscas";
  algo.author = "R Light Control";
  algo.acceptColors = 1;

  // Quantas células acendem a cada passo: Baixa, Média ou Alta
  var density = "Média";
  algo.properties = ["name:density|type:list|display:Densidade|values:Baixa,Média,Alta|write:setDensity|read:getDensity"];
  algo.setDensity = function (value) {
    density = value;
  };
  algo.getDensity = function () {
    return density;
  };

  // Cada célula acende ou não, por uma conta de embaralhar que muda a cada passo (a mesma sequência
  // sempre, sem sorteio)
  algo.rgbMap = function (width, height, rgb, step) {
    var limit = density === "Baixa" ? 12 : density === "Alta" ? 45 : 25;
    var map = new Array(height);
    for (var y = 0; y < height; y++) {
      map[y] = new Array(width);
      for (var x = 0; x < width; x++) {
        // Dois passos de um gerador de números (minstd) misturam a posição e o passo
        var hash = (x * 7919 + y * 104729 + step * 15485863 + 11) % 2147483647;
        hash = (hash * 48271) % 2147483647;
        hash = (hash * 48271) % 2147483647;
        map[y][x] = hash % 100 < limit ? rgb : 0;
      }
    }
    return map;
  };

  algo.rgbMapStepCount = function (width, height) {
    return 24;
  };

  return algo;
})()
